# @@ recursive
def factorial(n) {
    if n <= 1 {
        return 1
    }
    return py_int(n * factorial(py_int(n - 1)))
}
# @@ with a loop
def factorial_loop(n) {
    p = 1
    for k from 2 to py_int(n + 1) {
        p = py_int(p * k)
    }
    return p
}
